/** Sizes and positions that come from data (a bar's share, a shift's place on the day), as
 *  Tailwind fraction classes, because pages never use inline styles (owner rule, 20 October
 *  2026). Every class these return is generated by the `@source inline` lines in
 *  src/app/shadcn.css; change the steps there and here together. */
const POSITION_STEPS = 500;
const SIZE_STEPS = 100;

const clamp = (value: number) => Math.min(1, Math.max(0, Number.isFinite(value) ? value : 0));
const step = (fraction: number, steps: number) => Math.round(clamp(fraction) * steps);

/** A bar's length: `w-37/100` for 37%. A share above nothing never rounds away to nothing. */
export function widthOf(fraction: number) {
  const n = step(fraction, SIZE_STEPS);
  return `w-${n === 0 && fraction > 0 ? 1 : n}/${SIZE_STEPS}`;
}

/** A height, the same way: `h-37/100`. */
export function heightOf(fraction: number) {
  const n = step(fraction, SIZE_STEPS);
  return `h-${n === 0 && fraction > 0 ? 1 : n}/${SIZE_STEPS}`;
}

/** A point along the axis, from the left (or top) edge: `left-185/500`. */
export function leftOf(fraction: number) { return `left-${step(fraction, POSITION_STEPS)}/${POSITION_STEPS}`; }
export function topOf(fraction: number) { return `top-${step(fraction, POSITION_STEPS)}/${POSITION_STEPS}`; }

/** A stretch along the axis, from `start` to `end` (fractions of the whole): left and right
 *  edges, so a margin can inset it. */
export function stretchOf(start: number, end: number) {
  return `left-${step(start, POSITION_STEPS)}/${POSITION_STEPS} right-${POSITION_STEPS - step(end, POSITION_STEPS)}/${POSITION_STEPS}`;
}

/** A share of a ring (ProgressRing): `progress-at-37` for 37%. */
export function progressOf(fraction: number) { return `progress-at-${step(fraction, SIZE_STEPS)}`; }
